 *
 * Description:
 *   Initialize a non-reentrant spinlock object to its initial,
 *   unlocked state.
 *
 * Input Parameters:
 *   lock  - A reference to the spinlock object to be initialized.
 *
 * Returned Value:
 *   None.
 *
 ****************************************************************************/

#define spin_lock_init(l) \
  do \
    { \
      if (sizeof(*(l)) > 0u) \
        { \
          memset((FAR void *)(l), 0, sizeof(*(l))); \
        } \
    } \
  while (0)

/****************************************************************************
